INSERT INTO MonsterAction (monsterID, actionSection, actionName, actionUsage, actionRechargeMin, actionUsesPerDay, attackKind, attackBonus, attackReachFt, attackRangeFt, attackRangeLongFt, saveAbilityID, saveDc, actionDescription, sortOrder) VALUES ((SELECT monsterID FROM Monster WHERE monsterSlug = 'cloaker'), 'action', 'Multiattack', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The cloaker makes one Attach attack and two Tail attacks.', 1);
