INSERT INTO MonsterAction (monsterID, actionSection, actionName, actionUsage, actionRechargeMin, actionUsesPerDay, attackKind, attackBonus, attackReachFt, attackRangeFt, attackRangeLongFt, saveAbilityID, saveDc, actionDescription, sortOrder) VALUES ((SELECT monsterID FROM Monster WHERE monsterSlug = 'djinni'), 'trait', 'Magic Resistance', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The djinni has Advantage on saving throws against spells and other magical effects.', 2);
INSERT INTO MonsterAction (monsterID, actionSection, actionName, actionUsage, actionRechargeMin, actionUsesPerDay, attackKind, attackBonus, attackReachFt, attackRangeFt, attackRangeLongFt, saveAbilityID, saveDc, actionDescription, sortOrder) VALUES ((SELECT monsterID FROM Monster WHERE monsterSlug = 'djinni'), 'trait', 'Wishes', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The djinni has a 30 percent chance of knowing the Wish spell. If the djinni knows it, the djinni can cast it only on behalf of a non-genie creature who communicates a wish in a way the djinni can understand. If the djinni casts the spell for the creature, the djinni suffers none of the spell’s stress. Once the djinni has cast it three times, the djinni can’t do so again for 365 days.', 3);
