INSERT INTO MonsterAction (monsterID, actionSection, actionName, actionUsage, actionRechargeMin, actionUsesPerDay, attackKind, attackBonus, attackReachFt, attackRangeFt, attackRangeLongFt, saveAbilityID, saveDc, actionDescription, sortOrder) VALUES ((SELECT monsterID FROM Monster WHERE monsterSlug = 'gelatinous-cube'), 'trait', 'Ooze Cube', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, (SELECT abilityID FROM Ability WHERE abilityCode = 'STR'), 12, 'The cube fills its entire space and is transparent. Other creatures can enter that space, but a creature that does so is subjected to the cube’s Engulf and has Disadvantage on the saving throw. Creatures inside the cube have Total Cover, and the cube can hold one Large creature or up to four Medium or Small creatures inside itself at a time. As an action, a creature within 5 feet of the cube can pull a creature or an object out of the cube by succeeding on a DC 12 Strength (Athletics) check, and the puller takes 10 (3d6) Acid damage.', 1);
INSERT INTO MonsterActionDamage (monsterActionID, damageIndex, damageAvg, damageDiceCount, damageDiceSides, damageBonus, damageTypeID) VALUES ((SELECT monsterActionID FROM MonsterAction WHERE monsterID = (SELECT monsterID FROM Monster WHERE monsterSlug = 'gelatinous-cube') AND actionSection = 'trait' AND sortOrder = 1), 0, 10, 3, 6, 0, (SELECT damageTypeID FROM DamageType WHERE damageTypeName = 'Acid' COLLATE NOCASE));
INSERT INTO MonsterAction (monsterID, actionSection, actionName, actionUsage, actionRechargeMin, actionUsesPerDay, attackKind, attackBonus, attackReachFt, attackRangeFt, attackRangeLongFt, saveAbilityID, saveDc, actionDescription, sortOrder) VALUES ((SELECT monsterID FROM Monster WHERE monsterSlug = 'gelatinous-cube'), 'trait', 'Transparent', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, (SELECT abilityID FROM Ability WHERE abilityCode = 'WIS'), 15, 'Even when the cube is in plain sight, a creature must succeed on a DC 15 Wisdom (Perception) check to notice the cube if the creature hasn’t witnessed the cube move or otherwise act.', 2);
INSERT INTO MonsterAction (monsterID, actionSection, actionName, actionUsage, actionRechargeMin, actionUsesPerDay, attackKind, attackBonus, attackReachFt, attackRangeFt, attackRangeLongFt, saveAbilityID, saveDc, actionDescription, sortOrder) VALUES ((SELECT monsterID FROM Monster WHERE monsterSlug = 'gelatinous-cube'), 'action', 'Pseudopod', NULL, NULL, NULL, 'melee', 4, 5, NULL, NULL, NULL, NULL, 'Melee Attack Roll: +4, reach 5 ft. Hit: 12 (3d6 + 2) Acid damage.', 1);
INSERT INTO MonsterActionDamage (monsterActionID, damageIndex, damageAvg, damageDiceCount, damageDiceSides, damageBonus, damageTypeID) VALUES ((SELECT monsterActionID FROM MonsterAction WHERE monsterID = (SELECT monsterID FROM Monster WHERE monsterSlug = 'gelatinous-cube') AND actionSection = 'action' AND sortOrder = 1), 0, 12, 3, 6, 2, (SELECT damageTypeID FROM DamageType WHERE damageTypeName = 'Acid' COLLATE NOCASE));
INSERT INTO MonsterAction (monsterID, actionSection, actionName, actionUsage, actionRechargeMin, actionUsesPerDay, attackKind, attackBonus, attackReachFt, attackRangeFt, attackRangeLongFt, saveAbilityID, saveDc, actionDescription, sortOrder) VALUES ((SELECT monsterID FROM Monster WHERE monsterSlug = 'gelatinous-cube'), 'action', 'Engulf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, (SELECT abilityID FROM Ability WHERE abilityCode = 'DEX'), 12, 'The cube moves up to its Speed without provoking Opportunity Attacks. The cube can move through the spaces of Large or smaller creatures if it has room inside itself to contain them (see the Ooze Cube trait). Dexterity Saving Throw: DC 12, each creature whose space the cube enters for the first time during this move. Failure: 10 (3d6) Acid damage, and the target is engulfed. An engulfed target is suffocating, can’t cast spells with a Verbal component, has the Restrained condition, and takes 10 (3d6) Acid damage at the start of each of the cube’s turns. When the cube moves, the engulfed target moves with it. An engulfed target can try to escape by taking an action to make a DC 12 Strength (Athletics) check. On a successful check, the target escapes and enters the nearest unoccupied space. Success: Half damage, and the target moves to an unoccupied space within 5 feet of the cube. If there is no unoccupied space, the target fails the save instead.', 2);
