INSERT INTO MonsterAction (monsterID, actionSection, actionName, actionUsage, actionRechargeMin, actionUsesPerDay, attackKind, attackBonus, attackReachFt, attackRangeFt, attackRangeLongFt, saveAbilityID, saveDc, actionDescription, sortOrder) VALUES ((SELECT monsterID FROM Monster WHERE monsterSlug = 'ghost'), 'action', 'Etherealness', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The ghost casts the Etherealness spell, requiring no spell components and using Charisma as the spellcasting ability. The ghost is visible on the Material Plane while on the Border Ethereal and vice versa, but it can’t affect or be affected by anything on the other plane.', 3);
INSERT INTO MonsterSpell (monsterActionID, spellID, spellFrequency) VALUES ((SELECT monsterActionID FROM MonsterAction WHERE monsterID = (SELECT monsterID FROM Monster WHERE monsterSlug = 'ghost') AND actionSection = 'action' AND sortOrder = 3), (SELECT spellID FROM Spell WHERE spellSlug = 'etherealness'), 'at_will');
INSERT INTO MonsterAction (monsterID, actionSection, actionName, actionUsage, actionRechargeMin, actionUsesPerDay, attackKind, attackBonus, attackReachFt, attackRangeFt, attackRangeLongFt, saveAbilityID, saveDc, actionDescription, sortOrder) VALUES ((SELECT monsterID FROM Monster WHERE monsterSlug = 'ghost'), 'action', 'Horrific Visage', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, (SELECT abilityID FROM Ability WHERE abilityCode = 'WIS'), 13, 'Wisdom Saving Throw: DC 13, each creature in a 60-foot Cone that can see the ghost and isn’t an Undead. Failure: 10 (2d6 + 3) Psychic damage, and the target has the Frightened condition until the start of the ghost’s next turn. Success: The target is immune to this ghost’s Horrific Visage for 24 hours.', 4);
INSERT INTO MonsterActionDamage (monsterActionID, damageIndex, damageAvg, damageDiceCount, damageDiceSides, damageBonus, damageTypeID) VALUES ((SELECT monsterActionID FROM MonsterAction WHERE monsterID = (SELECT monsterID FROM Monster WHERE monsterSlug = 'ghost') AND actionSection = 'action' AND sortOrder = 4), 0, 10, 2, 6, 3, (SELECT damageTypeID FROM DamageType WHERE damageTypeName = 'Psychic' COLLATE NOCASE));
INSERT INTO MonsterAction (monsterID, actionSection, actionName, actionUsage, actionRechargeMin, actionUsesPerDay, attackKind, attackBonus, attackReachFt, attackRangeFt, attackRangeLongFt, saveAbilityID, saveDc, actionDescription, sortOrder) VALUES ((SELECT monsterID FROM Monster WHERE monsterSlug = 'ghost'), 'action', 'Possession', 'Recharge 6–6', 6, NULL, NULL, NULL, NULL, NULL, NULL, (SELECT abilityID FROM Ability WHERE abilityCode = 'CHA'), 13, 'Charisma Saving Throw: DC 13, one Humanoid the ghost can see within 5 feet. Failure: The target is possessed by the ghost; the ghost disappears, and the target has the Incapacitated condition and loses control of its body. The ghost now controls the body, but the target retains awareness. The ghost can’t be targeted by any attack, spell, or other effect, except ones that specifically target Undead. The ghost’s game statistics are the same, except it uses the possessed target’s Speed, as well as the target’s Strength, Dexterity, and Constitution modifiers. The possession lasts until the body drops to 0 Hit Points or the ghost leaves as a Bonus Action. When the possession ends, the ghost appears in an unoccupied space within 5 feet of the target, and the target is immune to this ghost’s Possession for 24 hours. Success: The target is immune to this ghost’s Possession for 24 hours.', 5);
