INSERT INTO MonsterActionDamage (monsterActionID, damageIndex, damageAvg, damageDiceCount, damageDiceSides, damageBonus, damageTypeID) VALUES ((SELECT monsterActionID FROM MonsterAction WHERE monsterID = (SELECT monsterID FROM Monster WHERE monsterSlug = 'kraken') AND actionSection = 'action' AND sortOrder = 4), 0, 33, 6, 10, 0, (SELECT damageTypeID FROM DamageType WHERE damageTypeName = 'Lightning' COLLATE NOCASE));
INSERT INTO MonsterAction (monsterID, actionSection, actionName, actionUsage, actionRechargeMin, actionUsesPerDay, attackKind, attackBonus, attackReachFt, attackRangeFt, attackRangeLongFt, saveAbilityID, saveDc, actionDescription, sortOrder) VALUES ((SELECT monsterID FROM Monster WHERE monsterSlug = 'kraken'), 'action', 'Swallow', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, (SELECT abilityID FROM Ability WHERE abilityCode = 'DEX'), 25, 'Dexterity Saving Throw: DC 25, one creature Grappled by the kraken (it can have up to four creatures swallowed at a time). Failure: 23 (3d8 + 10) Piercing damage. If the target is Large or smaller, it is swallowed and no longer Grappled. A swallowed creature has the Restrained condition, has Total Cover against attacks and other effects outside the kraken, and takes 24 (7d6) Acid damage at the start of each of its turns. If the kraken takes 50 damage or more on a single turn from a creature inside it, the kraken must succeed on a DC 25 Constitution saving throw at the end of that turn or regurgitate all swallowed creatures, each of which falls in a space within 10 feet of the kraken with the Prone condition. If the kraken dies, any swallowed creature no longer has the Restrained condition and can escape from the corpse using 15 feet of movement, exiting Prone.', 5);
