INSERT INTO MonsterAction (monsterID, actionSection, actionName, actionUsage, actionRechargeMin, actionUsesPerDay, attackKind, attackBonus, attackReachFt, attackRangeFt, attackRangeLongFt, saveAbilityID, saveDc, actionDescription, sortOrder) VALUES ((SELECT monsterID FROM Monster WHERE monsterSlug = 'night-hag'), 'trait', 'Magic Resistance', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The hag has Advantage on saving throws against spells and other magical effects.', 2);
INSERT INTO MonsterAction (monsterID, actionSection, actionName, actionUsage, actionRechargeMin, actionUsesPerDay, attackKind, attackBonus, attackReachFt, attackRangeFt, attackRangeLongFt, saveAbilityID, saveDc, actionDescription, sortOrder) VALUES ((SELECT monsterID FROM Monster WHERE monsterSlug = 'night-hag'), 'trait', 'Soul Bag', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The hag has a soul bag. While holding or carrying the bag, the hag can use its Nightmare Haunting action. The bag has AC 15, HP 20, and Resistance to all damage. The bag turns to dust if reduced to 0 Hit Points. If the bag is destroyed, any souls the bag is holding are released. The hag can create a new bag after 7 days.', 3);
INSERT INTO MonsterAction (monsterID, actionSection, actionName, actionUsage, actionRechargeMin, actionUsesPerDay, attackKind, attackBonus, attackReachFt, attackRangeFt, attackRangeLongFt, saveAbilityID, saveDc, actionDescription, sortOrder) VALUES ((SELECT monsterID FROM Monster WHERE monsterSlug = 'night-hag'), 'action', 'Multiattack', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The hag makes two Claw attacks.', 1);
INSERT INTO MonsterAction (monsterID, actionSection, actionName, actionUsage, actionRechargeMin, actionUsesPerDay, attackKind, attackBonus, attackReachFt, attackRangeFt, attackRangeLongFt, saveAbilityID, saveDc, actionDescription, sortOrder) VALUES ((SELECT monsterID FROM Monster WHERE monsterSlug = 'night-hag'), 'action', 'Claw', NULL, NULL, NULL, 'melee', 7, 5, NULL, NULL, NULL, NULL, 'Melee Attack Roll: +7, reach 5 ft. Hit: 13 (2d8 + 4) Slashing damage.', 2);
INSERT INTO MonsterActionDamage (monsterActionID, damageIndex, damageAvg, damageDiceCount, damageDiceSides, damageBonus, damageTypeID) VALUES ((SELECT monsterActionID FROM MonsterAction WHERE monsterID = (SELECT monsterID FROM Monster WHERE monsterSlug = 'night-hag') AND actionSection = 'action' AND sortOrder = 2), 0, 13, 2, 8, 4, (SELECT damageTypeID FROM DamageType WHERE damageTypeName = 'Slashing' COLLATE NOCASE));
INSERT INTO MonsterAction (monsterID, actionSection, actionName, actionUsage, actionRechargeMin, actionUsesPerDay, attackKind, attackBonus, attackReachFt, attackRangeFt, attackRangeLongFt, saveAbilityID, saveDc, actionDescription, sortOrder) VALUES ((SELECT monsterID FROM Monster WHERE monsterSlug = 'night-hag'), 'action', 'Nightmare Haunting (Requires Soul Bag)', '1/Day', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, 14, 'While on the Ethereal Plane, the hag casts Dream, using the same spellcasting ability as Spellcasting. Only the hag can serve as the spell’s messenger, and the target must be a creature the hag can see on the Material Plane. The spell fails and is wasted if the target is under the effect of the Protection from Evil and Good spell or within a Magic Circle spell. If the target takes damage from the Dream spell, the target’s Hit Point maximum decreases by an amount equal to that damage. If the spell kills the target, its soul is trapped in the hag’s soul bag, and the target can’t be raised from the dead until its soul is released.', 3);
INSERT INTO MonsterSpell (monsterActionID, spellID, spellFrequency) VALUES ((SELECT monsterActionID FROM MonsterAction WHERE monsterID = (SELECT monsterID FROM Monster WHERE monsterSlug = 'night-hag') AND actionSection = 'action' AND sortOrder = 3), (SELECT spellID FROM Spell WHERE spellSlug = 'dream'), 'at_will');
