INSERT INTO MonsterAction (monsterID, actionSection, actionName, actionUsage, actionRechargeMin, actionUsesPerDay, attackKind, attackBonus, attackReachFt, attackRangeFt, attackRangeLongFt, saveAbilityID, saveDc, actionDescription, sortOrder) VALUES ((SELECT monsterID FROM Monster WHERE monsterSlug = 'shield-guardian'), 'trait', 'Bound', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The guardian is magically bound to an amulet. While the guardian and its amulet are on the same plane of existence, the amulet’s wearer can telepathically call the guardian to travel to it, and the guardian knows the distance and direction to the amulet. If the guardian is within 60 feet of the amulet’s wearer, half of any damage the wearer takes (round up) is transferred to the guardian.', 1);
INSERT INTO MonsterAction (monsterID, actionSection, actionName, actionUsage, actionRechargeMin, actionUsesPerDay, attackKind, attackBonus, attackReachFt, attackRangeFt, attackRangeLongFt, saveAbilityID, saveDc, actionDescription, sortOrder) VALUES ((SELECT monsterID FROM Monster WHERE monsterSlug = 'shield-guardian'), 'trait', 'Regeneration', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The guardian regains 10 Hit Points at the start of each of its turns if it has at least 1 Hit Point.', 2);
INSERT INTO MonsterAction (monsterID, actionSection, actionName, actionUsage, actionRechargeMin, actionUsesPerDay, attackKind, attackBonus, attackReachFt, attackRangeFt, attackRangeLongFt, saveAbilityID, saveDc, actionDescription, sortOrder) VALUES ((SELECT monsterID FROM Monster WHERE monsterSlug = 'shield-guardian'), 'trait', 'Spell Storing', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'A spellcaster who wears the guardian’s amulet can cause the guardian to store one spell of level 4 or lower. To do so, the wearer must cast the spell on the guardian while within 5 feet of it. The spell has no effect but is stored within the guardian. Any previously stored spell is lost when a new spell is stored. The guardian can cast the spell stored with any parameters set by the original caster, requiring no spell components and using the caster’s spellcasting ability. The stored spell is then lost.', 3);
