INSERT INTO MonsterAction (monsterID, actionSection, actionName, actionUsage, actionRechargeMin, actionUsesPerDay, attackKind, attackBonus, attackReachFt, attackRangeFt, attackRangeLongFt, saveAbilityID, saveDc, actionDescription, sortOrder) VALUES ((SELECT monsterID FROM Monster WHERE monsterSlug = 'vampire-vampire'), 'action', 'Multiattack', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The vampire makes two Grave Strike attacks and uses Bite.', 1);
INSERT INTO MonsterAction (monsterID, actionSection, actionName, actionUsage, actionRechargeMin, actionUsesPerDay, attackKind, attackBonus, attackReachFt, attackRangeFt, attackRangeLongFt, saveAbilityID, saveDc, actionDescription, sortOrder) VALUES ((SELECT monsterID FROM Monster WHERE monsterSlug = 'vampire-vampire'), 'action', 'Grave Strike', NULL, NULL, NULL, 'melee', 9, 5, NULL, NULL, (SELECT abilityID FROM Ability WHERE abilityCode = 'STR'), 14, 'Melee Attack Roll: +9, reach 5 ft. Hit: 8 (1d8 + 4) Bludgeoning damage plus 7 (2d6) Necrotic damage. If the target is a Large or smaller creature, it has the Grappled condition (escape DC 14) from one of two hands.', 2);
INSERT INTO MonsterActionDamage (monsterActionID, damageIndex, damageAvg, damageDiceCount, damageDiceSides, damageBonus, damageTypeID) VALUES ((SELECT monsterActionID FROM MonsterAction WHERE monsterID = (SELECT monsterID FROM Monster WHERE monsterSlug = 'vampire-vampire') AND actionSection = 'action' AND sortOrder = 2), 0, 8, 1, 8, 4, (SELECT damageTypeID FROM DamageType WHERE damageTypeName = 'Bludgeoning' COLLATE NOCASE));
INSERT INTO MonsterActionDamage (monsterActionID, damageIndex, damageAvg, damageDiceCount, damageDiceSides, damageBonus, damageTypeID) VALUES ((SELECT monsterActionID FROM MonsterAction WHERE monsterID = (SELECT monsterID FROM Monster WHERE monsterSlug = 'vampire-vampire') AND actionSection = 'action' AND sortOrder = 2), 1, 7, 2, 6, 0, (SELECT damageTypeID FROM DamageType WHERE damageTypeName = 'Necrotic' COLLATE NOCASE));
INSERT INTO MonsterAction (monsterID, actionSection, actionName, actionUsage, actionRechargeMin, actionUsesPerDay, attackKind, attackBonus, attackReachFt, attackRangeFt, attackRangeLongFt, saveAbilityID, saveDc, actionDescription, sortOrder) VALUES ((SELECT monsterID FROM Monster WHERE monsterSlug = 'vampire-vampire'), 'action', 'Bite', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, (SELECT abilityID FROM Ability WHERE abilityCode = 'CON'), 17, 'Constitution Saving Throw: DC 17, one creature within 5 feet that is willing or that has the Grappled, Incapacitated, or Restrained condition. Failure: 6 (1d4 + 4) Piercing damage plus 13 (3d8) Necrotic damage. The target’s Hit Point maximum decreases by an amount equal to the Necrotic damage taken, and the vampire regains Hit Points equal to that amount. A Humanoid reduced to 0 Hit Points by this damage and then buried rises the following sunset as a Vampire Spawn under the vampire’s control.', 3);
INSERT INTO MonsterActionDamage (monsterActionID, damageIndex, damageAvg, damageDiceCount, damageDiceSides, damageBonus, damageTypeID) VALUES ((SELECT monsterActionID FROM MonsterAction WHERE monsterID = (SELECT monsterID FROM Monster WHERE monsterSlug = 'vampire-vampire') AND actionSection = 'action' AND sortOrder = 3), 0, 6, 1, 4, 4, (SELECT damageTypeID FROM DamageType WHERE damageTypeName = 'Piercing' COLLATE NOCASE));
INSERT INTO MonsterActionDamage (monsterActionID, damageIndex, damageAvg, damageDiceCount, damageDiceSides, damageBonus, damageTypeID) VALUES ((SELECT monsterActionID FROM MonsterAction WHERE monsterID = (SELECT monsterID FROM Monster WHERE monsterSlug = 'vampire-vampire') AND actionSection = 'action' AND sortOrder = 3), 1, 13, 3, 8, 0, (SELECT damageTypeID FROM DamageType WHERE damageTypeName = 'Necrotic' COLLATE NOCASE));
INSERT INTO MonsterAction (monsterID, actionSection, actionName, actionUsage, actionRechargeMin, actionUsesPerDay, attackKind, attackBonus, attackReachFt, attackRangeFt, attackRangeLongFt, saveAbilityID, saveDc, actionDescription, sortOrder) VALUES ((SELECT monsterID FROM Monster WHERE monsterSlug = 'vampire-vampire'), 'bonus_action', 'Charm', 'Recharge 5–6', 5, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 17, 'The vampire casts Charm Person, requiring no spell components and using Charisma as the spellcasting ability (spell save DC 17), and the duration is 24 hours. The Charmed target is a willing recipient of the vampire’s Bite, the damage of which doesn’t end the spell. When the spell ends, the target is unaware it was Charmed by the vampire.', 1);
INSERT INTO MonsterSpell (monsterActionID, spellID, spellFrequency) VALUES ((SELECT monsterActionID FROM MonsterAction WHERE monsterID = (SELECT monsterID FROM Monster WHERE monsterSlug = 'vampire-vampire') AND actionSection = 'bonus_action' AND sortOrder = 1), (SELECT spellID FROM Spell WHERE spellSlug = 'charm-person'), 'at_will');
INSERT INTO MonsterAction (monsterID, actionSection, actionName, actionUsage, actionRechargeMin, actionUsesPerDay, attackKind, attackBonus, attackReachFt, attackRangeFt, attackRangeLongFt, saveAbilityID, saveDc, actionDescription, sortOrder) VALUES ((SELECT monsterID FROM Monster WHERE monsterSlug = 'vampire-vampire'), 'bonus_action', 'Shape-Shift', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'If the vampire isn’t in sunlight or running water, it shape-shifts into a Tiny bat (Speed 5 ft., Fly Speed 30 ft.) or a Medium cloud of mist (Speed 5 ft., Fly Speed 20 ft. [hover]), or it returns to its vampire form. Anything it is wearing transforms with it. While in bat form, the vampire can’t speak. Its game statistics, other than its size and Speed, are unchanged. While in mist form, the vampire can’t take any actions, speak, or manipulate objects. It is weightless and can enter an enemy’s space and stop there. If air can pass through a space, the mist can do so, but it can’t pass through liquid. It has Resistance to all damage, except the damage it takes from sunlight.', 2);
INSERT INTO MonsterAction (monsterID, actionSection, actionName, actionUsage, actionRechargeMin, actionUsesPerDay, attackKind, attackBonus, attackReachFt, attackRangeFt, attackRangeLongFt, saveAbilityID, saveDc, actionDescription, sortOrder) VALUES ((SELECT monsterID FROM Monster WHERE monsterSlug = 'vampire-vampire'), 'legendary_action', 'Beguile', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 17, 'The vampire casts Command, requiring no spell components and using Charisma as the spellcasting ability (spell save DC 17). The vampire can’t take this action again until the start of its next turn.', 1);
INSERT INTO MonsterSpell (monsterActionID, spellID, spellFrequency) VALUES ((SELECT monsterActionID FROM MonsterAction WHERE monsterID = (SELECT monsterID FROM Monster WHERE monsterSlug = 'vampire-vampire') AND actionSection = 'legendary_action' AND sortOrder = 1), (SELECT spellID FROM Spell WHERE spellSlug = 'command'), 'at_will');
INSERT INTO MonsterAction (monsterID, actionSection, actionName, actionUsage, actionRechargeMin, actionUsesPerDay, attackKind, attackBonus, attackReachFt, attackRangeFt, attackRangeLongFt, saveAbilityID, saveDc, actionDescription, sortOrder) VALUES ((SELECT monsterID FROM Monster WHERE monsterSlug = 'vampire-vampire'), 'legendary_action', 'Deathless Strike', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The vampire moves up to half its Speed, and it makes one Grave Strike attack.', 2);
