INSERT INTO MonsterActionDamage (monsterActionID, damageIndex, damageAvg, damageDiceCount, damageDiceSides, damageBonus, damageTypeID) VALUES ((SELECT monsterActionID FROM MonsterAction WHERE monsterID = (SELECT monsterID FROM Monster WHERE monsterSlug = 'warhorse') AND actionSection = 'action' AND sortOrder = 1), 1, 5, 2, 4, 0, (SELECT damageTypeID FROM DamageType WHERE damageTypeName = 'Bludgeoning' COLLATE NOCASE));
